<script setup>
import { Head, router } from '@inertiajs/vue3'; import { ref } from 'vue'; import AppLayout from '../Layouts/AppLayout.vue';
const props=defineProps({records:Object,filters:Object}); const form=ref({interest_rate:0}); const note=ref(''); function save(){router.post('/cobros',form.value)} function pay(id){router.patch(`/cobros/${id}/pagar`)} function setNote(id){router.patch(`/cobros/${id}/nota`,{collection_note:note.value})} function remove(id){if(confirm('¿Eliminar factura?'))router.delete(`/cobros/${id}`)}
</script>
<template><Head title="Cobros"/><AppLayout><main class="module-page"><div class="module-header"><h2>Cobros y Cartera</h2><div><a class="row-action" href="/cobros/export/pdf">PDF</a><a class="row-action" href="/cobros/export/xlsx">XLSX</a></div></div><form class="module-form" @submit.prevent="save"><input v-model="form.number" required placeholder="Factura"><input v-model="form.concept" required placeholder="Concepto"><input v-model="form.amount" required type="number" min="0" placeholder="Monto"><input v-model="form.issued_at" required type="date"><input v-model="form.due_at" required type="date"><input v-model="form.interest_rate" type="number" min="0" placeholder="Interés %"><button class="module-primary">Registrar</button></form><div class="module-table-wrap"><table class="module-table"><tr><th>Factura</th><th>Concepto</th><th>Monto</th><th>Estado</th><th>Acciones</th></tr><tr v-for="row in records.data" :key="row.id"><td>{{row.number}}</td><td>{{row.concept}}</td><td>L {{row.amount}}</td><td>{{row.status}}</td><td><button v-if="row.status!=='Pagada'" class="row-action" @click="pay(row.id)">Marcar pagada</button><a class="row-action" :href="`/cobros/${row.id}/nota.pdf`">Nota PDF</a><input v-model="note" placeholder="Nota de cobro"><button class="row-action" @click="setNote(row.id)">Guardar nota</button><button class="row-action delete" @click="remove(row.id)">Eliminar</button></td></tr></table></div></main></AppLayout></template>
